Instruction: Add a function `adjacency_list(self) -> Dict[Node, List[Node]]` which returns the adjacency list of the graph by returning a dictionary where the keys are `Node` and the values are a list of `Node` which represent the nodes which can be reached from this one in one step.
The output dictionary should contain all nodes in the graph and only those nodes.

```python
from typing import List


class Node:
    '''Simple node (No duplicate edges between nodes)'''

    def __init__(self, id: int):
        self.id = id
        self.out_edges = []
        self.in_edges = []

    def __eq__(self, __value: object) -> bool:
        if not isinstance(__value, Node):
            return False
        else:
            return self.id == __value.id

    def __hash__(self) -> int:
        return self.id


class Graph:
    '''Simple directed graph (No duplicate edges between nodes, no duplicate nodes)'''

    def __init__(self, nodes: List[Node]):
        uniques = {}
        for node in nodes:
            if node in uniques.keys():
                raise RuntimeError
            else:
                uniques[node] = True
        self.nodes = nodes

    def add_edge(self, src: Node, dest: Node):
        assert src not in dest.in_edges
        assert dest not in src.out_edges
        src.out_edges.append(dest)
        dest.in_edges.append(src)

    def reverse_edges(self):
        reversed = Graph(list(map(lambda x: Node(x.id), self.nodes)))
        for i, node in enumerate(self.nodes):
            reversed.nodes[i].in_edges = node.out_edges
            reversed.nodes[i].out_edges = node.in_edges
        return reversed

    def DFS(self, src: Node) -> List[Node]:
        assert src in self.nodes

        visited = []
        to_visit = []
        to_visit.append(src)

        while len(to_visit) != 0:
            first = to_visit.pop()
            if first in visited:
                continue
            for n in first.out_edges:
                to_visit.append(n)

            visited.append(first)

        return visited
```

